<script setup lang="ts">
import {useProductivityStore} from '~/stores/productivity'; const store=useProductivityStore(); const toast=useToast(); const confirmClear=ref(false); const presetText=computed({get:()=>store.settings.timerPresets.join(', '),set:v=>store.updateSettings({timerPresets:v.split(',').map(Number).filter(x=>x>0)})}); const download=(x:string,n:string,t:string)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([x],{type:t}));a.download=n;a.click();URL.revokeObjectURL(a.href)}; const notify=async()=>{if(!('Notification'in window)){toast.add({title:'اعلان مرورگر پشتیبانی نمی‌شود',color:'warning'});return};const p=await Notification.requestPermission();toast.add({title:p==='granted'?'اعلان‌ها فعال شدند':'اجازه اعلان داده نشد',color:p==='granted'?'success':'warning'})};
</script>
<template><div class="max-w-4xl space-y-5"><div><h1 class="text-2xl font-black">تنظیمات</h1><p class="text-gray-500">رفتار سامانه را مطابق روش کارت تنظیم کن.</p></div><UCard><template #header>اجرای برنامه</template><div class="grid md:grid-cols-2 gap-4"><UFormField label="شروع روز"><UInput v-model="store.settings.workStart" type="time"/></UFormField><UFormField label="پایان روز"><UInput v-model="store.settings.workEnd" type="time"/></UFormField><UFormField label="هدف تمرکز روزانه (دقیقه)"><UInput v-model.number="store.settings.dailyStudyGoalMinutes" type="number" min="1"/></UFormField><UFormField label="چند دقیقه قبل یادآوری شود"><UInput v-model.number="store.settings.scheduleReminderMinutes" type="number" min="0"/></UFormField></div><div class="space-y-3 mt-5"><USwitch v-model="store.settings.autoAdvanceSchedule" label="حرکت خودکار سناریوی روز به کار بعدی"/><USwitch v-model="store.settings.notificationsEnabled" label="اعلان‌های سامانه"/><USwitch v-model="store.settings.motivationNotifications" label="پیام‌های انگیزشی گاه‌به‌گاه"/><UButton variant="soft" @click="notify">فعال‌سازی اعلان ویندوز/مرورگر</UButton></div></UCard><UCard><template #header>تایمرهای آماده</template><p class="text-sm text-gray-500 mb-3">اعداد را با کاما جدا کن؛ این‌ها همان دکمه‌های سریع صفحه تمرکز هستند.</p><UInput v-model="presetText"/><UFormField label="زمان پیش‌فرض تایمر دلخواه" class="mt-4"><UInput v-model.number="store.settings.customTimerDefault" type="number" min="1"/></UFormField></UCard><UCard><template #header>ساعت سکوت</template><div class="grid grid-cols-3 gap-3"><USwitch v-model="store.settings.quietHoursEnabled" label="فعال"/><UInput v-model="store.settings.quietStart" type="time"/><UInput v-model="store.settings.quietEnd" type="time"/></div></UCard><UCard><template #header>پشتیبان‌گیری</template><div class="flex flex-wrap gap-2"><UButton icon="i-lucide-download" @click="download(JSON.stringify(store.$state,null,2),'nexa-backup.json','application/json')">خروجی کامل JSON</UButton><UButton variant="soft" @click="localStorage.setItem('nexa-productivity-v2',JSON.stringify(store.$state));toast.add({title:'پشتیبان محلی به‌روزرسانی شد',color:'success'})">ذخیره فوری</UButton></div></UCard><UCard><template #header><span class="text-red-500">منطقه خطر</span></template><p class="text-sm text-gray-500 mb-3">تمام داده‌های محلی پاک می‌شوند.</p><UButton color="error" variant="soft" @click="confirmClear=true">پاک کردن همه داده‌ها</UButton></UCard><UModal v-model:open="confirmClear"><template #content><UCard><template #header>حذف همه داده‌ها؟</template><p>این عملیات برگشت‌پذیر نیست.</p><div class="flex justify-end gap-2 mt-4"><UButton variant="ghost" @click="confirmClear=false">انصراف</UButton><UButton color="error" @click="store.resetAllData();confirmClear=false">پاک کن</UButton></div></UCard></template></UModal></div></template>
